void point2ScreenCircle( geometryInS inputs[1], /* int circleLOD, */ float2 screenSize,
    bool isCulled, bool orthographic, float4x4 projection, bool isFOVdependent, inout LineStream<geometryInS> outStream  ) 
{ 
	 if (isCulled) return; 
    geometryInS outS  = inputs[0]; 
    int numSegment = 24; // circleLOD > 24 ? 24 : circleLOD; 
    float theta = 2.0 * 3.141592654 / numSegment; // circleLOD;  
    float cosine = cos(theta); 
    float sine = sin(theta);  
    float2x2 rotateMat = float2x2(cosine, sine, -sine, cosine); 
    float radius = inputs[0].radius; 
    if( isFOVdependent ) { 
		radius *= screenSize.x * 2; 
		if(orthographic) radius *= 0.5 * projection[0][0]; 
    } else { 
		radius *= outS.Pc.w; 
    } 
    float2 offset = float2(radius, 0.0); 
    float4 startEndPoint = inputs[0].Pc + float4(offset/screenSize.xy, 0.0, 0.0); 
    outS.Pc = startEndPoint; 
    outStream.Append( outS ); 
    for( int i = 0; i < numSegment-1; ++i ) { 
		 offset = mul(offset, rotateMat); 
        outS.Pc = inputs[0].Pc + float4(offset/screenSize.xy, 0.0, 0.0); 
        outStream.Append( outS ); 
    } 
    outS.Pc = startEndPoint; 
    outStream.Append( outS ); 
    outStream.RestartStrip(); 
}


void point2ScreenCircle( AttribArray<geometryInS>inputs, /* int circleLOD, */ float2 screenSize, bool isCulled,
    bool orthographic, float4x4 projection, bool isFOVdependent) 
{ 
	 if (isCulled) return; 
    geometryInS outS  = inputs[0]; 
    int numSegment = 24; // circleLOD > 24 ? 24 : circleLOD; 
    float theta = 2.0 * 3.141592654 /  numSegment; //circleLOD;  
    float cosine = cos(theta); 
    float sine = sin(theta);  
    float2x2 rotateMat = float2x2(cosine, -sine, sine, cosine); 
    float radius = inputs[0].radius; 
    if( isFOVdependent ) { 
		radius *= screenSize.x * 2; 
		if(orthographic) radius *= 0.5 * projection[0][0]; 
    } else { 
		radius *= outS.Pc.w; 
    } 
    float2 offset = float2(radius, 0.0); 
    float4 startEndPoint = inputs[0].Pc + float4(offset/screenSize.xy, 0.0, 0.0); 
    outS.Pc = startEndPoint; 
    emitVertex( outS ); 
    for( int i = 0; i < numSegment-1 ; ++i ) { 
		 offset = mul(rotateMat, offset); 
        outS.Pc = inputs[0].Pc + float4(offset/screenSize.xy, 0.0, 0.0); 
        emitVertex( outS ); 
    }  
    outS.Pc = startEndPoint; 
    emitVertex( outS ); 
    restartStrip(); 
}


void point2ScreenCircle(  /* int circleLOD, */ vec2 screenSize, bool isCulled,
    bool orthographic, mat4x4 projection, bool isFOVdependent) 
{ 
	 if (isCulled) return; 
    GEO_OUT_struct outS  = copyFromGEO_IN(0); 
    int numSegment = 24; // circleLOD > 24 ? 24 : circleLOD; 
    float theta = 2.0 * 3.141592654 /  numSegment; //circleLOD;  
    float cosine = cos(theta); 
    float sine = sin(theta);  
    mat2x2 rotateMat = mat2x2(cosine, sine, -sine, cosine); 
    float radius = GEO_IN[0].radius; 
    if( isFOVdependent ) { 
		radius *= screenSize.x * 2; 
		if(orthographic) radius *= 0.5 * projection[0][0]; 
    } else { 
		radius *= outS.Pc.w; 
    } 
    vec2 offset = vec2(radius, 0.0); 
    vec4 startEndPoint = gl_in[0].gl_Position + vec4(offset/screenSize.xy, 0.0, 0.0); 
    outS.Pc = startEndPoint; 
    EmitGeoStruct( outS ); 
    for( int i = 0; i < numSegment-1 ; ++i ) { 
		 offset = rotateMat * offset; 
        outS.Pc = gl_in[0].gl_Position + vec4(offset/screenSize.xy, 0.0, 0.0); 
        EmitGeoStruct( outS ); 
    }  
    outS.Pc = startEndPoint; 
    EmitGeoStruct( outS ); 
    EndPrimitive(); 
}


